import { Page, Locator, expect } from '@playwright/test';

export abstract class BasePage {
  readonly page: Page;

  constructor(page: Page) {
    this.page = page;
  }

  async goto(url: string = ''): Promise<void> {
    await this.page.goto(url);
    await this.page.waitForLoadState('domcontentloaded');
  }

  async clickElement(locator: Locator, timeout: number = 8000): Promise<void> {
    await locator.waitFor({ state: 'visible', timeout });
    await locator.click();
  }

  async fillElement(locator: Locator, text: string, timeout: number = 8000): Promise<void> {
    await locator.waitFor({ state: 'visible', timeout });
    await locator.fill(text);
  }

  async selectOption(locator: Locator, option: string): Promise<void> {
    await locator.waitFor({ state: 'visible', timeout: 8000 });
    await locator.selectOption(option);
  }

  async verifyVisible(locator: Locator, timeout: number = 8000): Promise<void> {
    await expect(locator).toBeVisible({ timeout });
  }
}

import { Page, Locator } from '@playwright/test';
import { BasePage } from './BasePage';

export class LandingAuthenticationPagePage extends BasePage {
  readonly pageUrl: string = 'https://app.example.com';
  readonly application_home_page: Locator;
  readonly username___mobile_number_field: Locator;
  readonly password_field: Locator;
  readonly login_to_dashboard_button: Locator;

  constructor(page: Page) {
    super(page);
    this.application_home_page = this.page.goto('https://app.example.com');
