    // Step 11: Fill Designation/Department Input
    await userManagementPage.enterDesignationDepartment(testData.inviteUser.designationDepartment);

    await userManagementPage.enterDepartment(testData.inviteUser.designationDepartment);

    // Step 12: Click Send Invitation Button
    await userManagementPage.clickSendInvitation();
  });
});

